#!/usr/bin/env bash
# ========================================================
# x-ui 全协议中转节点管理系统 - 一键安装脚本
# 支持 Debian / Ubuntu / CentOS / AlmaLinux / Rocky
# ========================================================

RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[0;33m'
BLUE='\033[0;34m'
CYAN='\033[0;36m'
PLAIN='\033[0m'

echo -e "${CYAN}"
echo "========================================================"
echo "    🛰️  x-ui 全协议中转与多服务器调度平台 - 一键部署"
echo "    支持全协议落地 (Socks5/VMess/VLESS/Trojan/SS/HTTP)"
echo "    自动封装为 VLESS + Reality 前置中转"
echo "    支持分组管理、流量限额熔断保护与前后端解耦"
echo "========================================================"
echo -e "${PLAIN}"

# 检查 root 权限
if [[ $EUID -ne 0 ]]; then
   echo -e "${RED}[错误] 请使用 root 权限运行此脚本！(例如: sudo bash ...)${PLAIN}"
   exit 1
fi

INSTALL_DIR="/usr/local/x-ui-relay-web"
SERVICE_FILE="/etc/systemd/system/x-relay-web.service"
CLI_FILE="/usr/bin/x-relay"
PORT=27095

echo -e "${YELLOW}[1/6] 正在安装系统基础依赖 (Python3, qrencode, curl)...${PLAIN}"
if command -v apt-get >/dev/null 2>&1; then
    apt-get update -y || apt-get update -y --allow-releaseinfo-change || true
    apt-get install -y python3 python3-pip qrencode curl wget tar gzip || true
elif command -v dnf >/dev/null 2>&1; then
    dnf install -y python3 python3-pip qrencode curl wget tar gzip epel-release || true
    dnf install -y qrencode || true
elif command -v yum >/dev/null 2>&1; then
    yum install -y python3 python3-pip curl wget tar gzip epel-release || true
    yum install -y qrencode || true
fi

echo -e "${YELLOW}[2/6] 检测底层 x-ui 运行环境...${PLAIN}"
DB_PATH=""
DEFAULT_USER="marginal"
DEFAULT_PASS="pbs483212595"

if [[ -f "/etc/x-ui-yg/x-ui-yg.db" ]]; then
    DB_PATH="/etc/x-ui-yg/x-ui-yg.db"
    echo -e "${GREEN}检测到 x-ui-yg 数据库: ${DB_PATH}${PLAIN}"
elif [[ -f "/etc/x-ui/x-ui.db" ]]; then
    DB_PATH="/etc/x-ui/x-ui.db"
    echo -e "${GREEN}检测到常规 x-ui 数据库: ${DB_PATH}${PLAIN}"
else
    echo -e "${YELLOW}[提示] 未在默认路径检测到 x-ui 数据库。${PLAIN}"
    echo -e "如果本机尚未安装 x-ui，推荐安装 x-ui-yg:"
    echo -e "  bash <(wget -qO- https://raw.githubusercontent.com/yonggekkk/x-ui-yg/main/install.sh)"
    echo -e "稍后中转系统仍将完成安装，可在安装 x-ui 后自动关联。"
    DB_PATH="/etc/x-ui-yg/x-ui-yg.db"
fi

# 尝试从 x-ui 数据库读取原面板账号密码
if [[ -f "$DB_PATH" ]]; then
    READ_INFO=$(python3 -c "
import sqlite3
try:
    conn = sqlite3.connect('$DB_PATH')
    c = conn.cursor()
    c.execute('SELECT username, password FROM users LIMIT 1;')
    row = c.fetchone()
    if row:
        print(f'{row[0]}|{row[1]}')
    conn.close()
except Exception:
    pass
" 2>/dev/null || true)
    if [[ -n "$READ_INFO" ]]; then
        DEFAULT_USER=$(echo "$READ_INFO" | cut -d'|' -f1)
        DEFAULT_PASS=$(echo "$READ_INFO" | cut -d'|' -f2)
        echo -e "${GREEN}已自动同步 x-ui 面板登录凭证 (用户名: ${DEFAULT_USER})${PLAIN}"
    fi
fi

echo -e "${YELLOW}[3/6] 部署程序源码到 ${INSTALL_DIR}...${PLAIN}"
mkdir -p "${INSTALL_DIR}/templates"

# 释放 app.py
cat << 'EOF_APP' | base64 -d | gzip -d > "${INSTALL_DIR}/app.py"

EOF_APP

# 释放 templates/index.html
cat << 'EOF_INDEX' | base64 -d | gzip -d > "${INSTALL_DIR}/templates/index.html"

EOF_INDEX

# 释放自身 install.sh 方便服务对外分发
cp -f "$0" "${INSTALL_DIR}/install.sh" 2>/dev/null || true

chmod +x "${INSTALL_DIR}/app.py"

# 生成系统配置文件 (若存在则保留原 token)
if [[ ! -f "/etc/x-relay-web.json" ]]; then
cat > "/etc/x-relay-web.json" << EOF_CFG
{
  "port": 27095,
  "username": "${DEFAULT_USER}",
  "password": "${DEFAULT_PASS}",
  "db_path": "${DB_PATH}",
  "default_sni": "apple.com",
  "listen": "0.0.0.0"
}
EOF_CFG
fi

echo -e "${YELLOW}[4/6] 配置 Systemd 系统服务...${PLAIN}"
cat > "${SERVICE_FILE}" << EOF_SVC
[Unit]
Description=x-ui Static IP Relay Web Service
After=network.target x-ui.service

[Service]
Type=simple
User=root
WorkingDirectory=${INSTALL_DIR}
ExecStart=/usr/bin/python3 ${INSTALL_DIR}/app.py
Restart=on-failure
RestartSec=5s
LimitNOFILE=65535

[Install]
WantedBy=multi-user.target
EOF_SVC

systemctl daemon-reload
systemctl enable x-relay-web.service
systemctl restart x-relay-web.service

echo -e "${YELLOW}[5/6] 配置系统防火墙放行端口 ${PORT}...${PLAIN}"
if command -v ufw >/dev/null 2>&1; then
    ufw allow ${PORT}/tcp >/dev/null 2>&1 || true
fi
if command -v firewall-cmd >/dev/null 2>&1; then
    firewall-cmd --zone=public --add-port=${PORT}/tcp --permanent >/dev/null 2>&1 || true
    firewall-cmd --reload >/dev/null 2>&1 || true
fi
if command -v iptables >/dev/null 2>&1; then
    iptables -I INPUT -p tcp --dport ${PORT} -j ACCEPT >/dev/null 2>&1 || true
fi

echo -e "${YELLOW}[6/6] 创建命令行快捷管理工具 ${CLI_FILE}...${PLAIN}"
cat > "${CLI_FILE}" << 'EOF_CLI'
#!/usr/bin/env bash
case "$1" in
    start)
        systemctl start x-relay-web
        echo "x-relay-web 服务已启动"
        ;;
    stop)
        systemctl stop x-relay-web
        echo "x-relay-web 服务已停止"
        ;;
    restart)
        systemctl restart x-relay-web
        echo "x-relay-web 服务已重启"
        ;;
    status)
        systemctl status x-relay-web --no-pager
        ;;
    log)
        journalctl -u x-relay-web -f -n 50
        ;;
    info)
        IP=$(curl -s4 --max-time 3 api.ipify.org || curl -s4 --max-time 3 icanhazip.com || echo "你的服务器IP")
        CFG="/etc/x-relay-web.json"
        PORT=$(grep -o '"port": *[0-9]*' $CFG | awk '{print $2}' 2>/dev/null || echo "27095")
        USER=$(grep -o '"username": *"[^"]*"' $CFG | cut -d'"' -f4 2>/dev/null || echo "marginal")
        PASS=$(grep -o '"password": *"[^"]*"' $CFG | cut -d'"' -f4 2>/dev/null || echo "pbs483212595")
        echo "=================================================="
        echo "中转管理面板访问信息:"
        echo "访问地址: http://${IP}:${PORT}"
        echo "登录账号: ${USER}"
        echo "登录密码: ${PASS}"
        echo "=================================================="
        ;;
    uninstall)
        read -p "确定要卸载 x-relay-web 中转管理服务吗？[y/N]: " confirm
        if [[ "$confirm" == [yY] ]]; then
            systemctl stop x-relay-web || true
            systemctl disable x-relay-web || true
            rm -f /etc/systemd/system/x-relay-web.service
            systemctl daemon-reload
            rm -rf /usr/local/x-ui-relay-web
            rm -f /usr/bin/x-relay
            echo "x-relay-web 已成功彻底卸载！"
        fi
        ;;
    *)
        echo "用法: x-relay {start|stop|restart|status|log|info|uninstall}"
        ;;
esac
EOF_CLI

chmod +x "${CLI_FILE}"

# 获取外网 IP
SERVER_IP=$(curl -s4 --max-time 3 api.ipify.org || curl -s4 --max-time 3 icanhazip.com || echo "你的服务器IP")

echo ""
echo -e "${GREEN}========================================================${PLAIN}"
echo -e "${GREEN}🎉 恭喜！x-ui 中转管理服务已成功安装并启动完成！${PLAIN}"
echo -e "${GREEN}========================================================${PLAIN}"
echo -e "Web 管理面板地址 : ${CYAN}http://${SERVER_IP}:${PORT}${PLAIN}"
echo -e "管理登录用户名   : ${YELLOW}${DEFAULT_USER}${PLAIN}"
echo -e "管理登录密码     : ${YELLOW}${DEFAULT_PASS}${PLAIN}"
echo -e "--------------------------------------------------------"
echo -e "${BLUE}快捷管理命令:${PLAIN}"
echo -e "  查看服务状态 : ${CYAN}x-relay status${PLAIN}"
echo -e "  重启中转服务 : ${CYAN}x-relay restart${PLAIN}"
echo -e "  查看运行日志 : ${CYAN}x-relay log${PLAIN}"
echo -e "  查看面板信息 : ${CYAN}x-relay info${PLAIN}"
echo -e "  卸载管理程序 : ${CYAN}x-relay uninstall${PLAIN}"
echo -e "--------------------------------------------------------"
echo -e "💡 提示: 如果使用独立前端调度面板，可在前端【⚙️ 服务器管理】中"
echo -e "   绑定此节点: 地址填 ${CYAN}http://${SERVER_IP}:${PORT}${PLAIN}，密码填 ${YELLOW}${DEFAULT_PASS}${PLAIN}"
echo -e "${GREEN}========================================================${PLAIN}"
